const dni1 = ["pon", "wt", "sr"];
const dni2 = ["czw", "pt"];
const wszystkie = [...dni1, ...dni2];
console.log(wszystkie); // ['pon', 'wt', 'sr', 'czw', 'pt']

const tab1 = [1, 2, 3];
const tab2 = [4, 5, 6];
const wynik = [0, ...tab1, 99, ...tab2, 100];
console.log(wynik); // [0, 1, 2, 3, 99, 4, 5, 6, 100]

const temperatury = [15, 22, 8];
const kopia = [...temperatury];
kopia.push(100);

console.log(kopia);        // [15, 22, 8, 100]
console.log(temperatury);  // [15, 22, 8] - NIEZMIENIONY

const zDuplikatami = new Set([1, 1, 2, 3, 3, 3, 4]);
const unikalne = [...zDuplikatami];
console.log(unikalne); // [1, 2, 3, 4]

const zamowienia = [{ id: 1, status: "nowe" }, { id: 2, status: "nowe" }];
const kopia = [...zamowienia];

kopia[0].status = "zrealizowane";
console.log(zamowienia[0].status); // "zrealizowane" - BLEDNIE, oryginal ZMIENIONY

const zamowienia = [{ id: 1, status: "nowe" }, { id: 2, status: "nowe" }];
const kopia = zamowienia.map(z => ({ ...z }));

kopia[0].status = "zrealizowane";
console.log(zamowienia[0].status); // "nowe" - POPRAWNIE, oryginal nienaruszony

function dodajDoListy(lista, element) {
  return [...lista, element];
}

const oryginalna = [1, 2, 3];
const nowa = dodajDoListy(oryginalna, 4);

console.log(nowa);        // [1, 2, 3, 4]
console.log(oryginalna);  // [1, 2, 3] - NIEZMIENIONA

function usunZListy(lista, indeks) {
  return [...lista.slice(0, indeks), ...lista.slice(indeks + 1)];
}

console.log(usunZListy([10, 20, 30, 40], 2)); // [10, 20, 40]

function wstawDoListy(lista, indeks, element) {
  return [...lista.slice(0, indeks), element, ...lista.slice(indeks)];
}

console.log(wstawDoListy([1, 2, 4, 5], 2, 3)); // [1, 2, 3, 4, 5]

function suma(...argumenty) {
  return argumenty.reduce((a, b) => a + b, 0);
}

const liczby = [1, 2, 3, 4];
console.log(suma(...liczby)); // 10

const grupa1 = ["Jan", "Ala"];
const grupa2 = ["Kuba", "Zosia"];
const wszyscy = [...grupa1, ...grupa2].sort((a, b) => a.localeCompare(b));
console.log(wszyscy); // ['Ala', 'Jan', 'Kuba', 'Zosia']

const liczby = [5, 3, 8, 1];
const posortowane = [...liczby].sort((a, b) => a - b);

console.log(posortowane); // [1, 3, 5, 8]
console.log(liczby);      // [5, 3, 8, 1] - NIEZMIENIONE

const koszyk = { produkty: ["chleb", "mleko"], suma: 15 };
const nowyKoszyk = { ...koszyk, produkty: [...koszyk.produkty, "maslo"] };

console.log(nowyKoszyk); // { produkty: ['chleb', 'mleko', 'maslo'], suma: 15 }
console.log(koszyk);     // { produkty: ['chleb', 'mleko'], suma: 15 } - NIEZMIENIONY

const liczby = [1, 2, 3, 4, 5];
const odwrocone = [...liczby].reverse();

console.log(odwrocone); // [5, 4, 3, 2, 1]
console.log(liczby);    // [1, 2, 3, 4, 5] - NIEZMIENIONE

function polaczTrzy(a, b, c) {
  return [...a, ...b, ...c];
}

console.log(polaczTrzy([1], [2, 3], [4, 5, 6])); // [1, 2, 3, 4, 5, 6]

const oceny = [3, 4, 5, 3, 4];
const unikalne = [...new Set(oceny)].sort((a, b) => a - b);
console.log(unikalne); // [3, 4, 5]

const oryginal = "Ala";
const odwrocony = [...oryginal].reverse().join("");
console.log(odwrocony); // "alA"

function pierwszeN(tablica, n) {
  return [...tablica.slice(0, n)]; // spread tu jest technicznie zbedny, slice() juz kopiuje
}

console.log(pierwszeN([1, 2, 3, 4, 5], 3)); // [1, 2, 3]

const zagniezdzone = [[1, 2], [3, 4]];
const kopia = [...zagniezdzone];

kopia[0].push(99);
console.log(zagniezdzone[0]); // [1, 2, 99] - oryginal TEZ zmieniony, bo wewnetrzna tablica jest wspoldzielona

const zagniezdzone = [[1, 2], [3, 4]];
const kopia = zagniezdzone.map(t => [...t]);

kopia[0].push(99);
console.log(zagniezdzone[0]); // [1, 2] - POPRAWNIE, oryginal nienaruszony

const liczby = [2, 3, 4];
const zNowym = [1, ...liczby];
console.log(zNowym); // [1, 2, 3, 4]
console.log(liczby);  // [2, 3, 4] - NIEZMIENIONE

function funkcjaTestowa(a, b, c) {
  return a + b + c;
}

const argumenty = [10, 20, 30];
console.log(funkcjaTestowa(...argumenty)); // 60

const pierwszy = 0;
const srodek = [1, 2, 3];
const ostatni = 4;

console.log([pierwszy, ...srodek, ostatni]); // [0, 1, 2, 3, 4]

function maxZTablic(...tablice) {
  return Math.max(...tablice.flat());
}

console.log(maxZTablic([1, 5], [9, 2], [3])); // 9

const pusta = [];
const liczby = [1, 2, 3];

console.log([...pusta] === pusta);     // false
console.log([...liczby] === liczby);   // false

const produkty = [{ nazwa: "A", cena: 100 }, { nazwa: "B", cena: 50 }];
const podniesioneCeny = produkty.map(p => ({ ...p, cena: p.cena + 10 }));

console.log(podniesioneCeny); // [{ nazwa: 'A', cena: 110 }, { nazwa: 'B', cena: 60 }]
console.log(produkty);        // [{ nazwa: 'A', cena: 100 }, { nazwa: 'B', cena: 50 }] - NIEZMIENIONE

